mapper.select:
SELECT *
FROM t_smart_job_log


        AND ( STRPOS(job_name,#{query.searchWord}) > 0
        OR STRPOS(param,#{query.searchWord}) > 0
        OR STRPOS(execute_result,#{query.searchWord}) > 0
        OR STRPOS(create_name,#{query.searchWord}) > 0
        )


        AND job_id = #{query.jobId}


        AND success_flag = #{query.successFlag}


        AND CAST(execute_start_time AS DATE) >= #{query.startTime}


        AND CAST(execute_start_time AS DATE) <= #{query.endTime}



    ORDER BY log_id DESC
